-- Recovered from the production migration ledger for deterministic rebuilds.
create or replace function public.v2_issue_attendance_qr(p_group_id uuid,p_attendance_date date) returns jsonb language plpgsql security definer set search_path=public as $$ declare uid uuid:=auth.uid(); s public.v2_attendance_sessions%rowtype; tok text; exp timestamptz; begin if uid is null then raise exception 'Authentication required'; end if; if not exists(select 1 from public.v2_groups g where g.id=p_group_id and g.teacher_id=uid) then raise exception 'Group not found'; end if; select * into s from public.v2_attendance_sessions where group_id=p_group_id and teacher_id=uid and attendance_date=p_attendance_date limit 1; if s.id is null then insert into public.v2_attendance_sessions(group_id,teacher_id,attendance_date) values(p_group_id,uid,p_attendance_date) returning * into s; end if; update public.v2_attendance_qr_tokens set active=false where attendance_session_id=s.id and teacher_id=uid and active=true; tok:=replace(gen_random_uuid()::text,'-',''); exp:=now()+interval '45 seconds'; insert into public.v2_attendance_qr_tokens(attendance_session_id,group_id,teacher_id,token,active,expires_at) values(s.id,p_group_id,uid,tok,true,exp); return jsonb_build_object('ok',true,'attendance_session_id',s.id,'token',tok,'expires_at',exp); end $$; grant execute on function public.v2_issue_attendance_qr(uuid,date) to authenticated; create or replace function public.v2_close_attendance_qr(p_attendance_session_id uuid) returns boolean language plpgsql security definer set search_path=public as $$ declare uid uuid:=auth.uid(); begin if uid is null then return false; end if; if not exists(select 1 from public.v2_attendance_sessions s where s.id=p_attendance_session_id and s.teacher_id=uid) then return false; end if; update public.v2_attendance_qr_tokens set active=false where attendance_session_id=p_attendance_session_id and teacher_id=uid and active=true; return true; end $$; grant execute on function public.v2_close_attendance_qr(uuid) to authenticated;

